import {
    isSiteGenerationActive,
    type ModelImportType,
    type SiteDataAddChoice,
} from '@lodex/common';
import { findCatalogModel } from '../catalogModel';
import { countStepsByType } from './buildLaunchSteps';
import { readLaunchSteps } from './wizardGeneration';

export type DataAddRefusal = {
    status: 409 | 400;
    error:
        | 'not_simplified'
        | 'loader_not_allowed'
        | 'import_type_not_allowed'
        | 'site_generation_in_progress';
};

// Validates a data add on a site generated by the wizard (its model is
// remembered and still in the catalog), with the loader of that model and no
// generation in progress, then starts the generation, in its data phase. The
// caller queues the import with `importJobId` as job id.
export type DataAddRequest = {
    loaderName: string;
    // the route the data comes by
    importType: ModelImportType;
    customLoader?: unknown;
};

export const startDataAddGeneration = async (
    ctx: any,
    choice: SiteDataAddChoice,
    { loaderName, importType, customLoader }: DataAddRequest,
    importJobId: string,
): Promise<{ runId: string } | DataAddRefusal> => {
    const [remembered, current] = await Promise.all([
        ctx.siteModel.findCurrent(),
        ctx.siteGeneration.findCurrent(),
    ]);
    const model = remembered
        ? findCatalogModel(
              ctx.catalogModels,
              remembered.modelId,
              ctx.availableLoaders,
          )
        : null;
    if (!model) {
        return { status: 409, error: 'not_simplified' };
    }
    // the import job would parse with the custom loader, not the one of the
    // model
    if (loaderName !== model.loader || (customLoader ?? null) !== null) {
        return { status: 400, error: 'loader_not_allowed' };
    }
    if (!model.importTypes.includes(importType)) {
        return { status: 400, error: 'import_type_not_allowed' };
    }
    if (isSiteGenerationActive(current?.status)) {
        return { status: 409, error: 'site_generation_in_progress' };
    }

    const steps = choice.relaunch
        ? await readLaunchSteps(ctx, model.launchOrder)
        : [];
    const generation = await ctx.siteGeneration.startDataAdd({
        importJobId,
        autoPublish: choice.autoPublish,
        steps,
        // without step to relaunch, there is no launch step to show
        estimate: steps.length > 0 ? countStepsByType(steps) : undefined,
    });
    return { runId: generation.runId };
};
